namespace DesktopCritters;
public static class Program {
 [STAThread] public static int Main(string[] args){try{if(args.Contains("--self-test"))return ModelTests.Run();if(args.Contains("--smoke-test"))return SmokeTests.Run(args.Last());using var mutex=new Mutex(true,"Local\\DesktopCritters.Windows",out bool created);if(!created){try{using var signal=EventWaitHandle.OpenExisting("Local\\DesktopCritters.ShowPanel");signal.Set();}catch(WaitHandleCannotBeOpenedException){}return 0;}var app=new System.Windows.Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var host=new Host(app);host.Start();app.Run();return 0;}catch(Exception e){if(args.Any(a=>a.StartsWith("--"))){Console.Error.WriteLine(e);return 1;}System.Windows.MessageBox.Show("桌宠启动失败："+e.Message,"桌面有点脏");return 1;}}
}
public sealed class Overlay:Window {
 public GameCanvas Canvas;private readonly World world;private readonly Action work,show;public bool Passthrough {get;private set;}
 [DllImport("user32.dll",EntryPoint="GetWindowLongPtrW")] private static extern nint GetLong(nint hwnd,int index);
 [DllImport("user32.dll",EntryPoint="SetWindowLongPtrW")] private static extern nint SetLong(nint hwnd,int index,nint value);
 [DllImport("user32.dll")] private static extern bool SetWindowPos(nint hwnd,nint after,int x,int y,int cx,int cy,uint flags);
 public Overlay(World w,Action onWork,Action onShow){world=w;work=onWork;show=onShow;Canvas=new GameCanvas(w);Content=Canvas;Title="桌面有点脏 · 虫群";WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;AllowsTransparency=true;Background=Brushes.Transparent;Topmost=true;ShowInTaskbar=false;ShowActivated=false;var area=SystemParameters.WorkArea;Left=area.Left;Top=area.Top;Width=area.Width;Height=area.Height;SourceInitialized+=(_,_)=>SetPassthrough(true);Canvas.MouseLeftButtonDown+=(_,e)=>{var p=e.GetPosition(Canvas);world.Press(new V(p.X,p.Y));CharacterLibrary.Shared.Observe(world,new V(p.X,p.Y));if(world.Tool==Tool.Grab||world.Tool==Tool.Broom)Canvas.CaptureMouse();Canvas.Focus();e.Handled=true;};Canvas.MouseMove+=(_,e)=>{var p=e.GetPosition(Canvas);world.Pointer=new V(p.X,p.Y);if(e.LeftButton==MouseButtonState.Pressed)world.Drag(world.Pointer);};Canvas.MouseLeftButtonUp+=(_,e)=>{world.Release();Canvas.ReleaseMouseCapture();};Canvas.LostMouseCapture+=(_,_)=>world.Release();PreviewKeyDown+=Key;}
 public void SetPassthrough(bool pass){var h=new WindowInteropHelper(this).Handle;if(h==0)return;long flags=GetLong(h,-20).ToInt64()|0x80;flags=pass?flags|0x20:flags&~0x20;SetLong(h,-20,new nint(flags));SetWindowPos(h,0,0,0,0,0,0x1|0x2|0x4|0x10|0x20);Passthrough=pass;}
 public bool NativePassthrough=>(GetLong(new WindowInteropHelper(this).Handle,-20).ToInt64()&0x20)!=0;
 public void Key(object sender,System.Windows.Input.KeyEventArgs e){if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==System.Windows.Input.Key.D0){show();e.Handled=true;return;}if(e.Key==System.Windows.Input.Key.Escape){work();e.Handled=true;return;}if(!world.Interactive)return;if(e.Key>=System.Windows.Input.Key.D1&&e.Key<=System.Windows.Input.Key.D7){world.Tool=(Tool)(e.Key-System.Windows.Input.Key.D1);world.Release();e.Handled=true;}else if(e.Key==System.Windows.Input.Key.Space){world.Paused=!world.Paused;world.Release();e.Handled=true;}else if(e.Key==System.Windows.Input.Key.Tab){world.NextSubject();e.Handled=true;}else if(e.Key==System.Windows.Input.Key.Return){world.Press(world.SubjectPoint());CharacterLibrary.Shared.Observe(world,world.SubjectPoint());world.Release();e.Handled=true;}}
}
public sealed class Host {
 public readonly World World;public readonly Overlay Overlay;public readonly ControlPanel Panel;private readonly System.Windows.Application app;private Forms.NotifyIcon? tray;private DispatcherTimer? timer;private readonly Stopwatch clock=Stopwatch.StartNew();private double last,lastSave,lastUi;private bool saveBlocked,soundEnabled;public bool Quitting;private EventWaitHandle? reopen;private RegisteredWaitHandle? reopenWait;private readonly string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DesktopCrittersWindows");
 private CharacterGallery? characters;
 public void ShowCharacters(){World.Release();if(characters==null){characters=new CharacterGallery(this){Owner=Overlay};characters.Closed+=(_,_)=>characters=null;}characters.Rebuild();characters.Show();characters.Activate();}
 private string SavePath=>Path.Combine(folder,"ecology-windows-v1.json");
 [StructLayout(LayoutKind.Sequential)] private struct ScreenPoint{public int X,Y;}
 [DllImport("user32.dll")] private static extern bool GetCursorPos(out ScreenPoint p);
 public Host(System.Windows.Application application){app=application;var area=SystemParameters.WorkArea;World=new World(area.Width,area.Height);try{if(File.Exists(SavePath))World.Restore(File.ReadAllText(SavePath));}catch(Exception){saveBlocked=true;World.Say("旧存档读取失败，原文件已保留；当前临时运行。");}World.AntAvatarEnabled=CharacterLibrary.Shared.Enabled;Overlay=new Overlay(World,Work,ShowPanel);Panel=new ControlPanel(this);}
 public void Start(){Overlay.Show();Panel.Owner=Overlay;Panel.Show();Panel.Activate();reopen=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\DesktopCritters.ShowPanel");reopenWait=ThreadPool.RegisterWaitForSingleObject(reopen,(_,_)=>app.Dispatcher.BeginInvoke(ShowPanel),null,Timeout.Infinite,false);tray=new Forms.NotifyIcon{Text="桌面有点脏 · 双击打开控制面板",Icon=System.Drawing.Icon.ExtractAssociatedIcon(Environment.ProcessPath!)??System.Drawing.SystemIcons.Application,Visible=true};var menu=new Forms.ContextMenuStrip();menu.Items.Add("打开控制面板",null,(_,_)=>ShowPanel());menu.Items.Add("回到工作 · 鼠标穿透",null,(_,_)=>Work());menu.Items.Add("角色换装与自定义图片",null,(_,_)=>ShowCharacters());menu.Items.Add("今日战报",null,(_,_)=>ShowReport());menu.Items.Add("暂停 / 继续",null,(_,_)=>{World.Paused=!World.Paused;World.Release();Panel.Refresh();});menu.Items.Add("退出桌面有点脏",null,(_,_)=>Exit());tray.ContextMenuStrip=menu;tray.DoubleClick+=(_,_)=>ShowPanel();SystemEvents.DisplaySettingsChanged+=DisplayChanged;timer=new DispatcherTimer(DispatcherPriority.Render){Interval=TimeSpan.FromMilliseconds(33)};timer.Tick+=Tick;last=clock.Elapsed.TotalSeconds;timer.Start();app.Exit+=(_,_)=>{SystemEvents.DisplaySettingsChanged-=DisplayChanged;timer.Stop();Save();tray.Visible=false;tray.Dispose();reopenWait?.Unregister(null);reopen?.Dispose();};}
 public void ShowPanel(){if(Quitting)return;if(!Overlay.IsVisible)Overlay.Show();if(!Panel.IsVisible)Panel.Show();Panel.WindowState=WindowState.Normal;Panel.Activate();Panel.Refresh();}
 public void SelectTool(Tool tool){World.Interactive=true;World.Tool=tool;World.Release();World.Watched=null;Overlay.SetPassthrough(false);Overlay.Activate();Overlay.Canvas.Focus();World.Say(new[]{"点桌面投食，也可以点虫体直接喂。","按住虫子，把它搬到另一边。","拍中蟑螂会爆浆，按4清理。","点按或拖动，扫走尸体、汁液和卵。","点虫或卵，观察它的一生。","点桌面放一枚蟑螂卵鞘。","点桌面放一枚蚁卵。"}[(int)tool]);Panel.Refresh();}
 public void Work(){World.Companion();Overlay.SetPassthrough(true);Panel.Refresh();}
 public void NewRound(){World.StartRound();Overlay.SetPassthrough(false);Overlay.Activate();Overlay.Canvas.Focus();Panel.Refresh();}
 public void ShowReport(){var window=new Window{Title="今日战报 · 桌面有点脏",Width=620,Height=630,MinWidth=460,MinHeight=400,Background=Art.Cream,Owner=Panel.IsVisible?Panel:null};var root=new DockPanel{Margin=new Thickness(18)};var actions=new UniformGrid{Columns=3,Margin=new Thickness(0,12,0,0)};var text=new TextBox{Text=World.ReportText(),IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,FontSize=14,Padding=new Thickness(14),Background=Brushes.White,BorderThickness=new Thickness(0)};foreach(var item in new[]{("让双方停火",Relation.Truce),("建交通商",Relation.Trade),("恢复交战",Relation.Hostile)}){var b=new Button{Content=item.Item1,Padding=new Thickness(8),Margin=new Thickness(3)};b.Click+=(_,_)=>{World.SetRelation(item.Item2);text.Text=World.ReportText();Save();};actions.Children.Add(b);}DockPanel.SetDock(actions,Dock.Bottom);root.Children.Add(actions);root.Children.Add(text);window.Content=root;window.Show();}
 public void ToggleSound(){soundEnabled=!soundEnabled;World.Say(soundEnabled?"音效已开启。":"音效已关闭。");Panel.Refresh();}
 public bool SoundEnabled=>soundEnabled;
 public void Save(){if(saveBlocked)return;try{Directory.CreateDirectory(folder);var temp=SavePath+".tmp";File.WriteAllText(temp,World.SaveJson());File.Move(temp,SavePath,true);}catch(Exception){World.Say("本机保存失败，请检查磁盘空间和目录权限。");}}
 public void Exit(){if(Quitting)return;Quitting=true;Save();app.Shutdown();}
 private void DisplayChanged(object? sender,EventArgs e)=>app.Dispatcher.BeginInvoke(()=>{World.Release();var area=SystemParameters.WorkArea;Overlay.Left=area.Left;Overlay.Top=area.Top;Overlay.Width=area.Width;Overlay.Height=area.Height;World.Resize(area.Width,area.Height);Panel.Left=Math.Clamp(Panel.Left,area.Left,Math.Max(area.Left,area.Right-Panel.Width));Panel.Top=Math.Clamp(Panel.Top,area.Top,Math.Max(area.Top,area.Bottom-Panel.Height));});
 private void Tick(object? sender,EventArgs e){double now=clock.Elapsed.TotalSeconds;World.Update(now-last);last=now;if(World.Sound){World.Sound=false;if(soundEnabled)System.Media.SystemSounds.Asterisk.Play();}if(World.Interactive&&GetCursorPos(out var pointer)){var p=Overlay.PointFromScreen(new Point(pointer.X,pointer.Y));World.Pointer=new V(p.X,p.Y);Overlay.Canvas.ShowPointer=p.X>=0&&p.Y>=0&&p.X<World.Width&&p.Y<World.Height;if(Panel.IsVisible){var q=Panel.PointFromScreen(new Point(pointer.X,pointer.Y));if(q.X>=0&&q.Y>=0&&q.X<Panel.ActualWidth&&q.Y<Panel.ActualHeight)Overlay.Canvas.ShowPointer=false;}}Overlay.Canvas.InvalidateVisual();if(now-lastUi>.2){Panel.Refresh();lastUi=now;}if(now-lastSave>15){Save();lastSave=now;}}
}
public sealed class ControlPanel:Window {
 private readonly Host host;private readonly TextBlock status=new(),notice=new(),observation=new();private readonly Button pause=new(),mode=new(),rate=new(),sound=new(),character=new();private readonly System.Collections.Generic.Dictionary<Tool,Button> tools=new();
 public ControlPanel(Host owner){host=owner;Title="桌面有点脏 · 控制台";Width=340;Height=Math.Min(770,SystemParameters.WorkArea.Height-30);WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;Background=Brushes.Transparent;AllowsTransparency=true;Topmost=true;ShowInTaskbar=true;Left=SystemParameters.WorkArea.Right-Width-18;Top=SystemParameters.WorkArea.Top+15;FontFamily=new FontFamily("Microsoft YaHei UI");FontSize=12;Foreground=Art.Forest;Resources.Add(typeof(Button),ButtonStyle());var frame=new Border{CornerRadius=new CornerRadius(22),Background=Art.Cream,BorderBrush=Art.Brush(0xD5DACA),BorderThickness=new Thickness(1)};var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};var root=new StackPanel{Margin=new Thickness(20)};scroll.Content=root;frame.Child=scroll;Content=frame;
  var header=new DockPanel();var hide=Make("−",()=>Hide());hide.Width=38;hide.ToolTip="收起面板；从任务栏或托盘双击图标找回";DockPanel.SetDock(hide,Dock.Right);header.Children.Add(hide);var title=new TextBlock{Text="桌面有点脏",FontSize=26,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center};title.MouseLeftButtonDown+=(_,e)=>{if(e.ButtonState==MouseButtonState.Pressed)DragMove();};header.Children.Add(title);root.Children.Add(header);root.Children.Add(new TextBlock{Text="喂一口，长一截。小心养成桌面巨兽。",Margin=new Thickness(0,10,0,18),Foreground=Art.Muted});status.TextWrapping=TextWrapping.Wrap;status.FontSize=14;status.LineHeight=26;status.Margin=new Thickness(0,0,0,12);root.Children.Add(status);character.Click+=(_,_)=>host.ShowCharacters();root.Children.Add(character);root.Children.Add(Make("开一局 · 2分30秒",()=>host.NewRound(),true));
  var snacks=new UniformGrid{Columns=3,Margin=new Thickness(0,8,0,6)};for(int n=0;n<6;n++){var snack=(Snack)n;snacks.Children.Add(Make(World.SnackNames[n],()=>{host.World.SelectedSnack=snack;host.SelectTool(Tool.Food);}));}root.Children.Add(snacks);var actions=new UniformGrid{Columns=4};foreach(var item in new[]{("投食 1",Tool.Food),("搬家 2",Tool.Grab),("拍死 3",Tool.Slipper),("扫把 4",Tool.Broom)}){var button=Make(item.Item1,()=>host.SelectTool(item.Item2));button.Height=53;actions.Children.Add(button);tools[item.Item2]=button;}root.Children.Add(actions);
  var modes=new UniformGrid{Columns=2,Margin=new Thickness(0,8,0,0)};mode.Content="回到工作 · Esc";mode.Click+=(_,_)=>host.Work();pause.Click+=(_,_)=>{host.World.Paused=!host.World.Paused;host.World.Release();Refresh();};modes.Children.Add(mode);modes.Children.Add(pause);root.Children.Add(modes);notice.TextWrapping=TextWrapping.Wrap;notice.Foreground=Art.Brush(0x65746A);notice.MinHeight=42;notice.Margin=new Thickness(3,12,3,5);root.Children.Add(notice);
  var extras=new UniformGrid{Columns=3};extras.Children.Add(Make("今日战报",()=>host.ShowReport()));sound.Click+=(_,_)=>host.ToggleSound();extras.Children.Add(sound);extras.Children.Add(Make("退出",()=>host.Exit()));root.Children.Add(extras);var observe=new UniformGrid{Columns=2,Margin=new Thickness(0,8,0,0)};observe.Children.Add(Make("观察 · 5",()=>host.SelectTool(Tool.Observe)));rate.Click+=(_,_)=>{if(host.World.Battle){host.World.Say("计分局固定正常速度。");return;}host.World.LifeRate=host.World.LifeRate==1?2:host.World.LifeRate==2?4:1;Refresh();};observe.Children.Add(rate);root.Children.Add(observe);
  var eggs=new UniformGrid{Columns=2,Margin=new Thickness(0,8,0,0)};eggs.Children.Add(Make("放蟑螂卵 · 6",()=>host.SelectTool(Tool.RoachEgg)));eggs.Children.Add(Make("放蚂蚁卵 · 7",()=>host.SelectTool(Tool.AntEgg)));root.Children.Add(eggs);var intruders=new UniformGrid{Columns=2};intruders.Children.Add(Make("引来蜘蛛",()=>{host.World.Summon(InvaderKind.Spider);Refresh();}));intruders.Children.Add(Make("引来甲虫",()=>{host.World.Summon(InvaderKind.Beetle);Refresh();}));root.Children.Add(intruders);observation.TextWrapping=TextWrapping.Wrap;observation.FontSize=11;observation.Foreground=Art.Muted;observation.Margin=new Thickness(3,10,3,0);root.Children.Add(observation);root.Children.Add(new TextBlock{Text="Tab选虫或卵 · 回车使用 · 空格暂停\nCtrl+0找回面板 · 托盘双击也可打开",TextAlignment=TextAlignment.Center,FontSize=10,Foreground=Art.Muted,Margin=new Thickness(0,12,0,0)});Closing+=(_,e)=>{if(!host.Quitting){e.Cancel=true;Hide();}};PreviewKeyDown+=host.Overlay.Key;Refresh();}
 internal static Style ButtonStyle(){var style=new Style(typeof(Button));style.Setters.Add(new Setter(Control.TemplateProperty,(ControlTemplate)XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border Background='{TemplateBinding Background}' CornerRadius='10' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border></ControlTemplate>")));style.Setters.Add(new Setter(Control.BackgroundProperty,Art.Brush(0xE8E9DF)));style.Setters.Add(new Setter(Control.ForegroundProperty,Art.Forest));style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(7,11,7,11)));style.Setters.Add(new Setter(FrameworkElement.MarginProperty,new Thickness(3)));style.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(0)));style.Setters.Add(new Setter(FrameworkElement.CursorProperty,Cursors.Hand));return style;}
 private static Button Make(string label,Action action,bool primary=false){var b=new Button{Content=label};if(primary){b.Background=Art.Forest;b.Foreground=Art.Cream;b.FontSize=16;}b.Click+=(_,_)=>action();return b;}
 public void Refresh(){character.Content="角色换装 · "+CharacterLibrary.Shared.DisplayName+"  ›";var w=host.World;status.Text=$"蟑螂帮  {w.Count(Species.Roach)}只 · 卵{w.Eggs.Count(e=>e.Species==Species.Roach)} · 粮{w.RoachFood}\n{(CharacterLibrary.Shared.Enabled?CharacterLibrary.Shared.DisplayName+"小队":"蚂蚁军团")}  {w.Count(Species.Ant)}只 · 卵{w.Eggs.Count(e=>e.Species==Species.Ant)} · 粮{w.AntFood}\n{(w.Battle?$"抢饭剩余 {Math.Ceiling(w.Remaining):0}秒":w.Interactive?"生态互动中":"自主成长中")}  ·  {w.RelationName}";pause.Content=w.Paused?"继续":"暂停";mode.Content=w.Interactive?"回到工作 · Esc":"陪伴中 · 鼠标穿透";rate.Content="生命 ×"+w.LifeRate;sound.Content=host.SoundEnabled?"音效：开":"音效：关";notice.Text=w.NoticeTime>0?w.Notice:"点虫喂食，巨型大餐能养出巨虫。";observation.Text=w.Observation;foreach(var t in tools){bool selected=w.Interactive&&t.Key==w.Tool;t.Value.Background=selected?Art.Forest:Art.Brush(0xE8E9DF);t.Value.Foreground=selected?Art.Cream:Art.Forest;}}
}
